// backend/audit/reporters/human.js
'use strict';

// Standard ANSI terminal colors
const ANSI = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m'
};

/**
 * Formats an audit report into a readable, color-coded human console report (Issue #77).
 * @param {Object} report - Audit report object generated by audit()
 * @param {Object} [options] - Output formatting options
 * @param {boolean} [options.colors=true] - Enable ANSI colors (defaults to true if TTY)
 * @returns {string} Formatted report string
 */
function formatHumanReport(report = {}, options = {}) {
  const useColors = options.colors !== undefined
    ? options.colors
    : (process.stdout && process.stdout.isTTY && !process.env.NO_COLOR);

  const c = useColors ? ANSI : {
    reset: '', bold: '', red: '', green: '', yellow: '', blue: '', cyan: '', gray: ''
  };

  const lines = [];
  const divider = '='.repeat(60);

  lines.push('');
  lines.push(`${c.bold}${c.cyan}DIMSEE SECURITY POSTURE AUDIT REPORT${c.reset}`);
  lines.push(`${c.gray}${divider}${c.reset}`);
  lines.push(`Timestamp: ${report.timestamp || new Date().toISOString()}`);

  const counts = report.counts || { error: 0, warn: 0, info: 0 };
  const passed = report.passed !== false;

  lines.push(`Status:    ${passed ? `${c.green}${c.bold}PASSED${c.reset}` : `${c.red}${c.bold}FAILED${c.reset}`}`);
  lines.push(
    `Summary:   ${c.red}${counts.error} error(s)${c.reset}, ` +
    `${c.yellow}${counts.warn} warning(s)${c.reset}, ` +
    `${c.blue}${counts.info} info${c.reset}`
  );
  lines.push(`${c.gray}${divider}${c.reset}`);
  lines.push('');

  const findings = report.findings || [];

  if (findings.length === 0) {
    lines.push(`${c.green}✔ No security posture findings detected. All checks passed!${c.reset}`);
  } else {
    findings.forEach((finding, index) => {
      let badge = `[${finding.severity.toUpperCase()}]`;
      if (finding.severity === 'error') {
        badge = `${c.red}${c.bold}${badge}${c.reset}`;
      } else if (finding.severity === 'warn') {
        badge = `${c.yellow}${c.bold}${badge}${c.reset}`;
      } else {
        badge = `${c.blue}${badge}${c.reset}`;
      }

      lines.push(`${index + 1}. ${badge} ${c.bold}${finding.title || finding.id}${c.reset}`);
      if (finding.rule) {
        lines.push(`   ${c.gray}Rule:${c.reset} ${finding.rule}`);
      }
      lines.push(`   ${c.gray}Detail:${c.reset} ${finding.message}`);
      if (finding.remediation) {
        lines.push(`   ${c.green}Remediation:${c.reset} ${finding.remediation}`);
      }
      lines.push('');
    });
  }

  lines.push(`${c.gray}${divider}${c.reset}`);
  lines.push('');

  return lines.join('\n');
}

module.exports = {
  formatHumanReport,
  ANSI
};
